def codepoints() -> set[int]:
    """游戏字体覆盖的 Unicode 码位集合"""
    global _CACHE
    if _CACHE is None:
        raw = base64.b85decode(_BLOB.encode('ascii'))
        out: set[int] = set()
        cur = prev = 0
        while cur < len(raw):
            shift = 0
            d = 0
            while True:
                b = raw[cur]
                cur += 1
                d |= (b & 0x7F) << shift
                shift += 7
                if not b & 0x80:
                    break
            prev += d
            out.add(prev)
        _CACHE = out
    return _CACHE


def can_render(ch: str) -> bool:
    """这个字符在 IIDX 里能不能显示"""
    o = ord(ch)
    return o < 0x80 or o in codepoints()
